"""Dimensions of the Hodge sectors containing the residue class, for the group generated by G and the swap sigma (X2<->Y2),
and for the dihedral reflection group D6 acting on the (X2,Y2)-plane."""
import oplib, itertools, sys
from hodge import core
from hodge.core import monomials, mul, pderiv, add, scale
from flint import nmod_mat
F, A, q = oplib.load()
p = oplib.P0
Fp = core.reduce_mod(F, p)
Fi = [pderiv(Fp, i, p) for i in range(6)]
def swap(P):
    return {(e[0], e[1], e[5], e[3], e[4], e[2]): v for e, v in P.items()}
def sector_dim(deg, pred, extra_sym=None):
    """dim of (S/J)_deg restricted to the subspace of monomial-combinations selected by pred (a G-character predicate)
    and symmetrized by extra_sym (a projector: P -> (P + sgn*sym(P))/2 given as function)."""
    mons = [m for m in monomials(deg) if pred(m)]
    # Jacobian ideal in this degree, projected onto the sector
    gens = []
    for i in range(6):
        for m in monomials(deg - 5):
            gens.append({tuple(a+b for a, b in zip(m, e)): v for e, v in Fi[i].items()})
    # project generator onto the G-sector (character predicate is monomial-wise), then symmetrize
    def proj(P):
        Pq = {e: v for e, v in P.items() if pred(e)}
        if extra_sym is not None:
            Pq = extra_sym(Pq)
        return Pq
    if extra_sym is not None:
        # sector basis: symmetrized monomials
        basis = {}
        for m in mons:
            s = extra_sym({m: 1})
            if s:
                key = tuple(sorted(s.items()))
                basis[key] = s
        secbasis = list(basis.values())
    else:
        secbasis = [{m: 1} for m in mons]
    idx = {m: i for i, m in enumerate(mons)}
    def vec(P):
        v = [0]*len(mons)
        for e, val in P.items(): v[idx[e]] = val % p
        return v
    rowsJ = [vec(proj(g)) for g in gens]
    rowsJ = [r for r in rowsJ if any(r)]
    rkJ = nmod_mat(len(rowsJ), len(mons), [x for r in rowsJ for x in r], p).rank() if rowsJ else 0
    rowsS = [vec(b) for b in secbasis]
    rkS = nmod_mat(len(rowsS), len(mons), [x for r in rowsS for x in r], p).rank()
    return rkS - rkJ, rkS, rkJ
inv2 = pow(2, -1, p)
def sym_plus(P):   # (P + swap P)/2
    return {e: v for e, v in add(scale(P, inv2, p), scale(swap(P), inv2, p), p).items() if v}
def sym_minus(P):
    return {e: v for e, v in add(scale(P, inv2, p), scale(swap(P), (p-1)*inv2 % p, p), p).items() if v}
charpred = lambda m: oplib.char(m) == (3, 0)
for deg in (6, 12, 18):
    full = sector_dim(deg, charpred)
    plus = sector_dim(deg, charpred, sym_plus)
    minus = sector_dim(deg, charpred, sym_minus)
    print(f'deg {deg}: G-invariant residue sector dim {full[0]} = sigma-even numerators {plus[0]} + sigma-odd numerators {minus[0]}')
# D6-det sector: numerators D6-invariant (polys in X0,X1,Y0,Y1, m=X2Y2, n=X2^6+Y2^6), tau-odd
def d6_inv_pred(m):   # monomial lies in a D6-invariant combination iff exponents of X2,Y2 are such that ... use Reynolds instead
    return True
def reynolds_d6(P):
    # average over D6 = <diag(zeta,zeta^-1), swap>: diag acts on monomial by zeta^(e2 - e5): keep only e2 == e5 mod 6, then symmetrize swap
    Pq = {e: v for e, v in P.items() if (e[2] - e[5]) % 6 == 0}
    return sym_plus(Pq)
yodd = lambda m: (m[3] + m[4] + m[5]) % 2 == 1
for deg in (6, 12):
    r = sector_dim(deg, yodd, reynolds_d6)
    print(f'deg {deg}: D6-det sector (D6-invariant Y-odd numerators) dim {r[0]}  (sector size {r[1]}, J part {r[2]})')
# full tau-sector for reference
for deg in (6, 12):
    r = sector_dim(deg, yodd)
    print(f'deg {deg}: full Y-odd sector dim {r[0]}')
